// npm run content:seed-sql
// Writes supabase/seed.sql from src/data/seed/places.ts so the database and the
// bundled demo data never drift apart. Places are inserted as unverified drafts.
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';

import { SEED_PLACES } from '../../src/data/seed/places';
import { LOCALES } from '../../src/data/types';

const q = (value: string | null) => (value === null ? 'null' : `'${value.replace(/'/g, "''")}'`);
const j = (value: unknown) => `${q(JSON.stringify(value))}::jsonb`;

const lines: string[] = [
  '-- Generated by scripts/content/build-seed-sql.ts. Do not edit by hand.',
  '-- Places are inserted as drafts (verified = false); review them before publishing.',
  '',
];

for (const p of SEED_PLACES) {
  lines.push(
    `insert into public.places (id, slug, lat, lng, category, period, verified, photo_url, photo_credit, facts) values (` +
      `${q(p.id)}, ${q(p.slug)}, ${p.lat}, ${p.lng}, ${q(p.category)}, ${q(p.period)}, false, ${q(p.photoUrl)}, ${q(p.photoCredit)}, ${j(p.facts)}) ` +
      `on conflict (id) do update set slug = excluded.slug, lat = excluded.lat, lng = excluded.lng, category = excluded.category, ` +
      `period = excluded.period, facts = excluded.facts, updated_at = now();`,
  );
  for (const locale of LOCALES) {
    const c = p.content[locale];
    lines.push(
      `insert into public.place_translations (place_id, locale, name, summary, story, highlights) values (` +
        `${q(p.id)}, ${q(locale)}, ${q(c.name)}, ${q(c.summary)}, ${q(c.story)}, ${j(c.highlights)}) ` +
        `on conflict (place_id, locale) do update set name = excluded.name, summary = excluded.summary, ` +
        `story = excluded.story, highlights = excluded.highlights;`,
    );
  }
  lines.push('');
}

const out = join(__dirname, '../../supabase/seed.sql');
writeFileSync(out, lines.join('\n'));
console.log(`Wrote ${out} (${SEED_PLACES.length} places)`);
